const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");
const fs = require("fs");

async function main() {
  try {
    // Get API key from environment or use placeholder
    const apiKey = process.env.CROSSMINT_API_KEY || "your-api-key-here";
    const recoverySecret = process.env.CROSSMINT_RECOVERY_SECRET || "your-recovery-secret-here";

    const crossmint = createCrossmint({ apiKey });
    const wallets = CrossmintWallets.from(crossmint);

    // Create a wallet with server-side recovery
    const wallet = await wallets.createWallet({
      chain: "base-sepolia",
      recovery: { type: "server", secret: recoverySecret },
    });

    // Write successful result
    const result = {
      chain: "base-sepolia",
      type: "evm",
      address: wallet.address,
    };

    fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify(result, null, 2));
    console.log("Wallet created successfully:", result);
  } catch (error) {
    // Write error result
    const result = {
      chain: "base-sepolia",
      type: "evm",
      error: error.message,
    };

    fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify(result, null, 2));
    console.error("Error creating wallet:", error.message);
    throw error;
  }
}

main().catch((error) => {
  console.error("Script failed:", error);
  process.exit(1);
});

